import'package:flutter/material.dart';import'science_solvers.dart';
class DeterministicSciencePage extends StatefulWidget{const DeterministicSciencePage({super.key});@override State<DeterministicSciencePage>createState()=>_DeterministicSciencePageState();}
class _DeterministicSciencePageState extends State<DeterministicSciencePage>{String model='mechanics';SolverResult?result;final a=TextEditingController(text:'2'),b=TextEditingController(text:'5'),c=TextEditingController(text:'0');void solve(){final x=double.tryParse(a.text)??0,y=double.tryParse(b.text)??1,z=double.tryParse(c.text)??0;setState(()=>result=switch(model){'mechanics'=>ScienceSolvers.mechanics(u:z,a:x,t:y),'projectile'=>ScienceSolvers.projectile(speed:x,angleDeg:y),'capacitor'=>ScienceSolvers.capacitor(x,y,z==0?.001:z,5),'wave'=>ScienceSolvers.wave(x,y,z==0?2:z),'gas'=>ScienceSolvers.idealGas(x,y,z==0?1:z),'seismic'=>ScienceSolvers.seismic(x,y,z==0?3.5:z),'plate'=>ScienceSolvers.plate(0,36,x,y,z==0?1000:z),_=>ScienceSolvers.decay(x,y,z)});} @override Widget build(BuildContext context)=>ListView(padding:const EdgeInsets.all(20),children:[Text('Deterministic Science',style:Theme.of(context).textTheme.headlineMedium),DropdownButtonFormField(value:model,items:const[DropdownMenuItem(value:'mechanics',child:Text('Mechanics')),DropdownMenuItem(value:'projectile',child:Text('Projectile')),DropdownMenuItem(value:'capacitor',child:Text('RC capacitor')),DropdownMenuItem(value:'wave',child:Text('Waves')),DropdownMenuItem(value:'gas',child:Text('Ideal gas')),DropdownMenuItem(value:'seismic',child:Text('Seismic waves')),DropdownMenuItem(value:'plate',child:Text('Plate motion')),DropdownMenuItem(value:'decay',child:Text('Radioactive decay'))],onChanged:(v)=>setState(()=>model=v!)),TextField(controller:a,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Parameter A')),TextField(controller:b,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Parameter B')),TextField(controller:c,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Parameter C')),FilledButton(onPressed:solve,child:const Text('Run deterministic solver')),if(result!=null)...result!.metrics.entries.map((e)=>ListTile(title:Text(e.key),trailing:Text(e.value.toStringAsFixed(4))))]);}